# Manual analysis of changes since we don't have the library functions
inputs = ['biux', 'yux', 'wy', 'yiy', 'xwhbw']
outputs = ['biyvwwdvj', 'yyvwwdvj', 'wy', 'yiy', 'dvjwhbw']

print("Detailed analysis of changes:")
for i in range(len(inputs)):
    if inputs[i] != outputs[i]:
        print(f"Index {i}: '{inputs[i]}' -> '{outputs[i]}'")
        # Find where they differ
        min_len = min(len(inputs[i]), len(outputs[i]))
        diff_pos = -1
        for j in range(min_len):
            if inputs[i][j] != outputs[i][j]:
                diff_pos = j
                break

        if diff_pos == -1:
            # One string is prefix of other
            if len(inputs[i]) < len(outputs[i]):
                print(f"  Append: '{outputs[i][len(inputs[i]):]}'")
            else:
                print(f"  Remove: '{inputs[i][len(outputs[i]):]}'")
        else:
            # Find what changed
            print(f"  Position {diff_pos} differs")
            if diff_pos < len(inputs[i]) and diff_pos < len(outputs[i]):
                print(f"  Changed '{inputs[i][diff_pos]}' to '{outputs[i][diff_pos]}'")
            elif diff_pos >= len(inputs[i]):
                print(f"  Added '{outputs[i][diff_pos:]}' starting at position {diff_pos}")
            elif diff_pos >= len(outputs[i]):
                print(f"  Removed from position {diff_pos}")
        print()

